	@echo "✅ Backups created with timestamp!\n"

ssh:
	@echo "🔐 Setting up SSH..."
	@sh ssh/ssh.sh

clean:
	@echo "🧹 Removing symlinks..."
	@rm -f ~/.zshrc && echo "  ✅ Removed ~/.zshrc" || true
	@rm -f ~/.p10k.zsh && echo "  ✅ Removed ~/.p10k.zsh" || true
